import { FC, useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, Flex, Modal, type ModalProps, notification, Segmented, Tag, Typography } from 'antd';
import cn from 'classnames';

import CalendarIcon from 'assets/images/icons/calendar-with-clock.svg?react';
import {
	EPaymentModel,
	EPaymentModelMap,
	useBrand,
	useBrandSlice,
	useOffersPostsSendToPmCreateMutation,
} from 'entities/Brand';
import { COUNTRIES } from 'shared/consts';
import { EYmPageScreen } from 'shared/typings';
import { sendYmEvent } from 'shared/utils';

import styles from './OfferDetailsPopup.module.scss';

interface IOfferDetailsPopupProps extends ModalProps {}

export const OfferDetailsPopup: FC<IOfferDetailsPopupProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const paymentModel = EPaymentModel.CPA; //TODO: get from api
	const { handleSendClick } = useBrand();
	const { setIsOpenDetailsPopup, isOpenDetailsPopup, offer } = useBrandSlice();
	const [sendToPm, { isLoading: isSendingToPm, isSuccess: isSentToPmSuccess }] = useOffersPostsSendToPmCreateMutation();

	const detailItems = [
		{
			term: t('Модели оплаты'),
			description: (
				<Flex align="flex-start" gap={8}>
					<Tag color={EPaymentModelMap[EPaymentModel.CPA].color} bordered={false}>
						{EPaymentModelMap[paymentModel].text}
					</Tag>
					<div>
						{EPaymentModelMap[paymentModel].fullName}
						<br />
						{EPaymentModelMap[paymentModel].description}
					</div>
				</Flex>
			),
		},
		{
			term: t('Ставка'),
			description: (
				<>
					{offer?.actual_rates?.map((rate) => (
						<div key={rate.name} style={{ marginBottom: 12 }}>
							{rate.name}
							<div>
								{rate.tariffs.map((tariff) => {
									const unit = tariff.rates.is_percentage ? '%' : offer?.currency.sign || '';
									const isEquals = Number(tariff.rates.min) === Number(tariff.rates.max);

									return (
										<div>
											{tariff.name} - {tariff.rates.min}
											{unit} {!isEquals && '-'} {!isEquals && tariff.rates.max}
											{!isEquals && unit}
										</div>
									);
								})}
							</div>
						</div>
					))}
				</>
			),
		},
		{ term: t('Гео'), description: offer?.countries?.map((country) => COUNTRIES[country.alpha_2]).join(', ') },
		{
			term: t('Описание платного задания'),
			description: (
				<span
					dangerouslySetInnerHTML={{ __html: offer?.description || '' }}
					className={styles.detailsPopup__innerHtml}
				/>
			),
		},
	];

	const postItems = [
		{
			term: t('Иллюстрация к посту'),
			description: offer?.posts[0]?.images[0]?.image ? (
				<img src={offer.posts[0].images[0].image} alt={offer?.name} className={styles.detailsPopup__img} />
			) : (
				<></>
			),
		},
		{
			term: t('Текст поста'),
			description: (
				<span
					dangerouslySetInnerHTML={{ __html: offer?.posts[0]?.content || '' }}
					className={styles.detailsPopup__innerHtml}
				/>
			),
		},
		{
			term: t('Правила редактирования'),
			description: t('Допускается незначительное изменение, например, смены мужского рода глаголов на женский'),
		},
	];

	const segmentedOptions = [
		{ label: t('Детали'), value: detailItems },
		{
			label: t('Пост'),
			value: postItems,
			...(!offer?.posts.length && {
				disabled: true,
				className: styles.detailsPopup__disabled,
			}),
		},
	];

	const [segment, setSegment] = useState(detailItems);

	const handleSendExampleClick = () => {
		sendYmEvent('click_send_example_post', { page_screen: EYmPageScreen.OFFER_SCREEN });
		// 	TODO:
		sendToPm(offer?.posts[0]?.uuid || '');
	};

	useEffect(() => {
		if (isSentToPmSuccess) {
			notification.success({
				message: t('Пост успешно отправлен'),
				placement: 'bottom',
				showProgress: true,
				pauseOnHover: true,
			});
		}
	}, [isSentToPmSuccess, t]);

	if (!offer) return null;

	return (
		<Modal
			open={isOpenDetailsPopup}
			onCancel={() => setIsOpenDetailsPopup(false)}
			className={cn(className, styles.detailsPopup)}
			title={offer.name}
			destroyOnHidden
			footer={null}
			classNames={{
				header: styles.detailsPopup__modalHeader,
				content: styles.detailsPopup__modal,
			}}
			{...props}>
			<Segmented
				defaultValue={detailItems}
				options={segmentedOptions}
				onChange={(value) => {
					if (value === postItems) {
						sendYmEvent('click_post_advCampaign', {
							page_screen: EYmPageScreen.OFFER_SCREEN,
							event_type: 'click_button',
						});
					}
					setSegment(value);
				}}
				block
				className={styles.detailsPopup__segmented}
			/>

			<dl>
				{segment.map((item) => (
					<Flex gap={4} vertical key={item.term} className={styles.detailsPopup__line}>
						<dt>
							<Typography.Text type={'secondary'} className={styles.detailsPopup__dt}>
								{item.term}
							</Typography.Text>
						</dt>
						<dd>{item.description}</dd>
					</Flex>
				))}
			</dl>

			<Flex gap={4} vertical className={styles.detailsPopup__footer}>
				<Flex gap={4}>
					<Button type="primary" block icon={<CalendarIcon />} onClick={handleSendClick} disabled={!offer.posts.length}>
						{t('Опубликовать задание')}
					</Button>
				</Flex>
				<Button
					type="link"
					block
					onClick={handleSendExampleClick}
					disabled={!offer.posts.length}
					loading={isSendingToPm}>
					{t('Отправить пример поста в личку')}
				</Button>
			</Flex>
		</Modal>
	);
};
