import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Flex, Typography } from 'antd';
import cn from 'classnames';

import { type OfferRead, useBrandSlice } from 'entities/Brand';
import { EYmPageScreen } from 'shared/typings';
import { sendYmEvent } from 'shared/utils';

import styles from './OfferCardForBrand.module.scss';

interface IOfferCardForBrandProps extends HTMLAttributes<HTMLDivElement> {
	offer: OfferRead;
}

export const OfferCardForBrand: FC<IOfferCardForBrandProps> = ({ className, offer, ...props }) => {
	//const paymentModel = EPaymentModel.CPA; //TODO: get from api
	const { t } = useTranslation();
	const { setIsOpenDetailsPopup, setOffer, setVisitedOffer, visitedOffers } = useBrandSlice();

	const handleOfferClick = () => {
		sendYmEvent('click_detail_advCampaign', { page_screen: EYmPageScreen.BRAND_SCREEN });
		setOffer(offer);
		setVisitedOffer(offer.uuid);
		setIsOpenDetailsPopup(true);
	};

	return (
		<>
			<Flex vertical {...props} className={cn(className, styles.offerCard)} onClick={handleOfferClick}>
				<img className={styles.offerCard__image} src={offer.image} alt={offer.name} />
				<Flex gap={2} vertical className={styles.offerCard__body}>
					<Typography.Paragraph
						className={styles.offerCard__lineClamp}
						type={visitedOffers.includes(offer.uuid) ? 'secondary' : undefined}
						ellipsis={{
							rows: 3,
						}}>
						{offer.name}
					</Typography.Paragraph>
					<Typography.Text className={styles.offerCard__rate} type="secondary">
						{t('Ставка')}{' '}
						{Object.values(offer.grouped_rates)
							.filter((rate) => !!rate)
							.map((rate) => `${t('до')} ${rate}`)
							.join(', ')}
					</Typography.Text>
					{/*<Tag className={styles.offerCard__tags} color={EPaymentModelMap[paymentModel].color} bordered={false}>
						{EPaymentModelMap[paymentModel].text}
					</Tag>*/}
				</Flex>
			</Flex>
		</>
	);
};
