import { useTranslation } from 'react-i18next';
import { useNavigate } from 'react-router-dom';

import { useChannelsListQuery } from 'entities/Channel';
import { CHANNELS_LIMIT } from 'features/Filters';
import { EPaginationParams } from 'features/Pagination';
import { useCommonSlice } from 'shared/hooks';
import { EMainRoutes, EYmPageScreen } from 'shared/typings';
import { sendYmEvent } from 'shared/utils';

import { useBrandSlice } from './useBrandSlice';

export const useBrand = () => {
	const { t } = useTranslation();
	const navigate = useNavigate();
	const { offer, setIsOpenDetailsPopup } = useBrandSlice();
	const { setIsOpenFrozenPopup } = useCommonSlice();
	const { data: channelList } = useChannelsListQuery({ [EPaginationParams.LIMIT]: CHANNELS_LIMIT });

	const createPost = () => {
		// TODO:
		setIsOpenDetailsPopup(false);
		navigate(`/${EMainRoutes.POST}/${EMainRoutes.CREATE}?offerId=${offer?.uuid}`);
	};

	const openFrozenPopup = () => {
		setIsOpenDetailsPopup(false);
		setIsOpenFrozenPopup(true);
	};

	const handleSendClick = () => {
		sendYmEvent('click_publish_task', { page_screen: EYmPageScreen.OFFER_SCREEN });
		channelList?.results.length ? createPost() : openFrozenPopup();
	};

	return {
		t,
		handleSendClick,
	};
};
